// Reload refetches the object from the database
// using the primary keys with an executor.
func (o *EventTransaction) Reload(ctx context.Context, exec boil.ContextExecutor) error {
	ret, err := FindEventTransaction(ctx, exec, o.TenantID, o.UserID, o.DeviceID, o.Endpoint, o.RoomID, o.TXNID)
	if err != nil {
		return err
	}

	*o = *ret
	return nil
}

// ReloadAll refetches every row with matching primary key column values
// and overwrites the original object slice with the newly updated slice.
func (o *EventTransactionSlice) ReloadAll(ctx context.Context, exec boil.ContextExecutor) error {
	if o == nil || len(*o) == 0 {
		return nil
	}

	slice := EventTransactionSlice{}
	var args []any
	for _, obj := range *o {
		pkeyArgs := queries.ValuesFromMapping(reflect.Indirect(reflect.ValueOf(obj)), eventTransactionPrimaryKeyMapping)
		args = append(args, pkeyArgs...)
	}

	sql := "SELECT \"event_transactions\".* FROM \"event_transactions\" WHERE " +
		strmangle.WhereClauseRepeated(string(dialect.LQ), string(dialect.RQ), 1, eventTransactionPrimaryKeyColumns, len(*o))

	q := queries.Raw(sql, args...)

	err := q.Bind(ctx, exec, &slice)
	if err != nil {
		return errors.Wrap(err, "dbpostgres: unable to reload all in EventTransactionSlice")
	}

	*o = slice

	return nil
}

// EventTransactionExists checks if the EventTransaction row exists.
func EventTransactionExists(ctx context.Context, exec boil.ContextExecutor, tenantID string, userID string, deviceID string, endpoint string, roomID string, tXNID string) (bool, error) {
	var exists bool
	sql := "select exists(select 1 from \"event_transactions\" where \"tenant_id\"=$1 AND \"user_id\"=$2 AND \"device_id\"=$3 AND \"endpoint\"=$4 AND \"room_id\"=$5 AND \"txn_id\"=$6 limit 1)"

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, sql)
		fmt.Fprintln(writer, tenantID, userID, deviceID, endpoint, roomID, tXNID)
	}
	row := exec.QueryRowContext(ctx, sql, tenantID, userID, deviceID, endpoint, roomID, tXNID)

	err := row.Scan(&exists)
	if err != nil {
		return false, errors.Wrap(err, "dbpostgres: unable to check if event_transactions exists")
	}

	return exists, nil
}

// Exists checks if the EventTransaction row exists.
func (o *EventTransaction) Exists(ctx context.Context, exec boil.ContextExecutor) (bool, error) {
	return EventTransactionExists(ctx, exec, o.TenantID, o.UserID, o.DeviceID, o.Endpoint, o.RoomID, o.TXNID)
}
